mapper.sql:
where 1=1

		and cwse_llave = #{llaveTabla}


		and cwse_estado = #{estado}


		and cwse_servicio = #{servicio}


		and cwse_usuario = #{usuario}


		and dwse_fecha >= #{fechaMin}


		and dwse_fecha  <   #{fechaMax}


		and cwse_documento = #{documento}


		and cwse_modificador = #{modificador}


		and cwse_transaccion = #{transaccion}


		and dwse_fechaejecucion >= #{fechaEjecucionMin}


		and dwse_fechaejecucion  <   #{fechaEjecucionMax}


		and cwse_sincrona = #{sincrona}
